"""File inspection, history and explicit start-review dialog."""
EXTRA = r'''
<section class="panel storage-filters"><div class="form-grid"><label>Älter als (Datum ggf. geschätzt)<select id="file-age" onchange="renderFiles()"><option value="0">Beliebiges Alter</option><option value="7">7 Tage</option><option value="30">30 Tage</option><option value="90">90 Tage</option></select></label><label>Mindestgröße in MiB<input id="file-min-size" type="number" min="0" step="1" value="0" oninput="renderFiles()"></label><label>Ansicht<select id="file-view" onchange="saveFileView()"><option value="list">Liste</option><option value="cards">Kacheln</option></select></label><div><button class="secondary" onclick="selectFilteredFiles()">Gefilterte Dateien auswählen</button><p class="muted small">Geschützte Dateien werden ausgelassen. Löschen verlangt weiterhin eine eigene Bestätigung.</p></div></div></section>
<dialog id="file-detail"><div class="section-heading"><h2 id="detail-title">Dateidetails</h2><button class="quiet" onclick="closeFileDetails()">Schließen</button></div><img id="detail-image" class="detail-image" alt="Gespeicherte Modellvorschau" hidden><p id="detail-status" role="status"></p><div id="detail-content" hidden><label>Druckplatte<select id="detail-plate" onchange="renderPlateDetails()"></select></label><p id="plate-facts"></p><p id="plate-warnings" class="muted small"></p><div id="start-mappings"></div><button type="button" class="quiet" id="refresh-start-context" onclick="refreshPrintContext()">Druckerangaben aktualisieren</button><p id="start-help" class="muted small">Zuordnungen sind Vorschläge. Material, Farbe und tatsächlich eingelegte Rolle prüfen. Die Auswahl ändert weder AMS-Stammdaten noch Drucksteuerungsprofile. Bei einer anderen Rolle Profil im AMS prüfen und danach hier die Druckerangaben aktualisieren. Die Slicer-Einstellungen der 3MF bleiben erhalten.</p><label class="inline-check"><input id="start-override" type="checkbox">Abweichungen bei Material oder Farbe bewusst zulassen.</label><fieldset id="start-options"><legend>Optionen für diesen Druck</legend><label class="inline-check"><input type="checkbox" name="bed_leveling" checked>Druckbett nivellieren</label><label class="inline-check"><input type="checkbox" name="flow_cali">Dynamische Flusskontrolle</label><label class="inline-check"><input type="checkbox" name="vibration_cali">Vibrationskompensation</label><label class="inline-check"><input type="checkbox" name="timelapse">Zeitraffer</label></fieldset><p class="muted small">Diese Optionen gelten nur für diesen Start. Verbrauchszuschlag und dessen Buchungsregel werden separat in den Einstellungen verwaltet.</p><button id="start-review-button" onclick="reviewPrintStart()">Druckstart prüfen …</button><section id="print-start-review" class="summary-box" hidden><h3>Diesen Druck starten?</h3><ul id="print-start-summary"></ul><label class="inline-check"><input id="start-bed-clear" type="checkbox">Druckplatte ist frei, sauber und für diesen Druck vorbereitet.</label><button id="start-confirm-button" onclick="confirmPrintStart()">Jetzt drucken</button></section></div><h3>Druck- und Verbrauchshistorie</h3><p class="muted small">Bis zu 30 zu diesem Dateinamen passende Aufträge. Gleichnamige, später ersetzte Dateien lassen sich historisch nicht sicher unterscheiden.</p><div id="file-history"></div></dialog>
<style>
.storage-filters{margin:18px 0;padding:0;border:0;box-shadow:none;background:none}.storage-filters .form-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.inline-check{flex-direction:row;align-items:center;margin:12px 0}.detail-image{display:block;width:180px;max-height:160px;object-fit:contain;margin:12px auto}#file-detail{width:min(850px,96vw);max-height:90vh;overflow:auto;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:18px;padding:24px}#file-detail::backdrop{background:#0008}#start-options{border:1px solid var(--line);border-radius:12px;margin:18px 0}.mapping-line{padding:12px 0;border-bottom:1px solid var(--line)}.file-cards table,.file-cards tbody{display:block}.file-cards thead{display:none}.file-cards tbody{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px}.file-cards tr{display:flex;position:relative;flex-direction:column;padding:18px;border:1px solid var(--line);border-radius:12px;background:var(--soft)}.file-cards td{display:block;border:0;padding:6px 0}.file-cards td:first-child{position:absolute;right:12px;top:12px}.file-cards td:nth-child(2){padding-right:30px;font-weight:650;max-width:none!important}.file-cards .file-preview-controls{display:flex;flex-wrap:wrap;margin-top:auto}.file-cards .file-preview{width:100%;height:130px}.file-cards .file-preview-controls button{font-size:13px;padding:8px}#file-history .history-row{padding:12px 0;border-bottom:1px solid var(--line)}@media(max-width:700px){.storage-filters .form-grid{grid-template-columns:1fr 1fr}#file-detail{padding:16px}}
</style>
<script>
let detailFile=null,detailMetadata=null,detailContext=null,detailReview=null,detailGeneration=0,startingPrint=false,detailReady=false,detailLoad=null,detailContextVersion=0;
function filteredFiles(){const query=byId('file-search').value.toLocaleLowerCase(),min=Math.max(0,Number(byId('file-min-size').value)||0)*1048576,days=Number(byId('file-age').value);return files.filter(f=>f.name.toLocaleLowerCase().includes(query)&&f.size>=min&&(!days||fileDate(f.modified)>0&&fileDate(f.modified)<Date.now()-days*86400000))}
function saveFileView(){try{localStorage.setItem('plus-file-view',byId('file-view').value)}catch{}renderFiles()}
function selectFilteredFiles(){if(busy)return;selected.clear();for(const f of filteredFiles())if(!f.blocked)selected.add(f.token);byId('delete-review').hidden=true;renderFiles();byId('delete-files').disabled=!selected.size}
function cancelDetailLoad(load=detailLoad){if(!load||load.complete)return;load.cancelled=true;const body=new URLSearchParams({file:load.file,viewer:load.viewer,csrf_token:csrf});if(load.ticket)body.set('ticket',load.ticket);fetch('/storage/details/cancel',{method:'POST',body,keepalive:true}).catch(()=>{});if(detailLoad===load)detailLoad=null}
function closeFileDetails(){if(startingPrint)return;cancelDetailLoad();detailGeneration++;byId('file-detail').close();detailReview=null}
function invalidatePrintReview(){detailReview=null;byId('print-start-review').hidden=true;byId('start-bed-clear').checked=false}
function detailStatus(message){byId('detail-status').textContent=message}
async function storageJSON(path,options={}){const r=await fileFetch(path,options),d=await r.json();if(!r.ok)throw Error(d.error||'Abfrage fehlgeschlagen.');return d}
function applyDetailMetadata(metadata,ready){const selectedPlate=byId('detail-plate').value,chosen=Object.fromEntries([...document.querySelectorAll('[data-filament]')].map(s=>[s.dataset.filament,s.value]));detailMetadata=metadata;detailReady=ready;const plate=byId('detail-plate');plate.replaceChildren();for(const p of metadata.plates)plate.add(new Option('Druckplatte '+p.index,p.index));if([...plate.options].some(o=>o.value===selectedPlate))plate.value=selectedPlate;plate.disabled=false;renderPlateDetails();for(const s of document.querySelectorAll('[data-filament]'))if(chosen[s.dataset.filament]&&[...s.options].some(o=>o.value===chosen[s.dataset.filament]&&!o.disabled)){s.value=chosen[s.dataset.filament];paintPrintPressure(s,s.parentElement.querySelector('[data-pressure-for]'),s.parentElement.querySelector('a'))}}
async function showFileDetails(file){
 if(busy||startingPrint)return;
 cancelDetailLoad();const load={file:file.token,viewer:globalThis.crypto?.randomUUID?.()||(Date.now()+'-'+Math.random().toString(36).slice(2)),complete:false,ticket:null};detailLoad=load;
 detailFile=file;detailMetadata=null;detailContext=null;detailReady=false;invalidatePrintReview();const generation=++detailGeneration;
 byId('detail-title').textContent=file.name;byId('detail-content').hidden=false;byId('detail-plate').replaceChildren();byId('detail-plate').disabled=true;byId('plate-facts').textContent='Druckplatten und Filamentdaten werden geprüft …';byId('plate-warnings').textContent='';byId('start-mappings').replaceChildren();byId('start-review-button').disabled=true;byId('file-history').textContent='Historie wird geladen …';byId('start-override').checked=false;
 const img=byId('detail-image');img.hidden=!file.preview_url;if(file.preview_url)img.src=file.preview_url;byId('file-detail').showModal();detailStatus('Optionen können bereits eingestellt werden. Druckdaten werden im Hintergrund geprüft.');
 let contextError='';const contextVersion=++detailContextVersion;
 if(!file.blocked)storageJSON('/api/storage/start-context').then(ctx=>{if(generation!==detailGeneration||contextVersion!==detailContextVersion)return;detailContext=ctx;if(detailMetadata)applyDetailMetadata(detailMetadata,detailReady)}).catch(e=>{if(generation!==detailGeneration||contextVersion!==detailContextVersion)return;contextError=e.message;if(detailReady)detailStatus('Dateidetails geladen. Druckstart nicht verfügbar: '+contextError)});
 storageJSON('/api/storage/history?file='+encodeURIComponent(file.token)).then(d=>{if(generation!==detailGeneration)return;const box=byId('file-history');box.replaceChildren();for(const row of d.entries){const p=document.createElement('p');p.className='history-row';p.textContent=new Date(row.created_at).toLocaleString('de-DE')+' · '+row.state+(row.cancelled?' · Abbruch':'')+' · gebucht '+Number(row.grams).toLocaleString('de-DE',{maximumFractionDigits:2})+' g';box.append(p)}if(!d.entries.length)box.textContent='Keine passende Druckhistorie vorhanden.'}).catch(e=>{if(generation===detailGeneration)byId('file-history').textContent=e.message});
 if(!file.name.toLowerCase().endsWith('.3mf')){detailStatus('Reiner G-Code: Historie verfügbar. Sicherer Druckstart benötigt die zugehörige geslicte 3MF mit Druckplatten- und Filamentdaten.');return}
 try{
  let data=await storageJSON('/storage/details',{method:'POST',body:new URLSearchParams({file:file.token,viewer:load.viewer,csrf_token:csrf})});const ticket=data.ticket;load.ticket=ticket;if(generation!==detailGeneration){cancelDetailLoad(load);return}
  while(data.state==='loading'){
   if(generation!==detailGeneration)return;
   if(data.draft_metadata&&!detailMetadata)applyDetailMetadata(data.draft_metadata,false);
   detailStatus((detailMetadata?'Vorläufige Plattendaten vorhanden; Auswahl ist bereits möglich. ':'Optionen sind bereits bedienbar. ')+'Start erst nach vollständiger Prüfung. '+(data.received!=null?sizeLabel(data.received)+' / '+sizeLabel(file.size):''));
   await new Promise(r=>setTimeout(r,1000));if(generation!==detailGeneration)return;
   data=await storageJSON('/api/storage/details?ticket='+encodeURIComponent(ticket));
  }
  if(generation!==detailGeneration){cancelDetailLoad(load);return}load.complete=true;if(data.state==='cancelled')throw Error('Dateiprüfung abgebrochen.');if(data.state==='error')throw Error(data.error);
  applyDetailMetadata(data.metadata,true);
  detailStatus(file.blocked?'Druckstart gesperrt: '+file.blocked:contextError?'Dateidetails geladen. Druckstart nicht verfügbar: '+contextError:'Dateidetails geprüft. Druckplatte und Filamentzuordnung prüfen.');
 }catch(e){cancelDetailLoad(load);if(generation===detailGeneration){detailReady=false;byId('start-review-button').disabled=true;detailStatus(e.message)}}
}
function renderPlateDetails(){invalidatePrintReview();if(!detailMetadata)return;const p=detailMetadata.plates.find(p=>String(p.index)===byId('detail-plate').value);byId('detail-image').hidden=!p.preview;if(p.preview)byId('detail-image').src=p.preview;byId('plate-facts').textContent=detailMetadata.model+' · '+(p.seconds==null?'Druckzeit unbekannt':Math.round(p.seconds/60)+' Min.')+' · '+(p.grams==null?'Gewicht unbekannt':p.grams.toLocaleString('de-DE',{maximumFractionDigits:2})+' g')+' · Düse '+(p.nozzle||'unbekannt')+' mm · '+p.objects.join(', ');byId('plate-warnings').textContent=p.warnings.length?'Dateihinweise: '+p.warnings.map(w=>({'bed_temperature_too_high_than_filament':'Betttemperatur laut Slicer möglicherweise zu hoch für das Filament','not_generate_timelapse':'Druckdatei enthält keinen vorbereiteten Zeitraffer'}[w]||'Zusätzlicher Slicerhinweis vorhanden; Datei bei Bedarf in Bambu Studio prüfen')).join(' · '):'';const mappings=byId('start-mappings');mappings.replaceChildren();for(const f of p.filaments){const label=document.createElement('label');label.className='mapping-line';label.textContent='Filament '+f.id+' · '+f.material+' · '+f.color+' · '+(f.grams??'?')+' g';const select=document.createElement('select'),pressure=document.createElement('small'),profileLink=document.createElement('a');pressure.dataset.pressureFor=f.id;profileLink.textContent='Drucksteuerung im AMS prüfen / ändern ↗';profileLink.target='_blank';profileLink.rel='noopener';select.dataset.filament=f.id;select.add(new Option('Eingelegte Rolle auswählen …',''));for(const t of detailContext?.slots||[]){const option=new Option(t.label+' · '+t.material+' · '+t.color+' · '+t.spool_name+' ('+(t.spool_material||'')+' '+(t.spool_color||'')+')',t.slot);option.disabled=!t.available||!t.spool_id;select.add(option)}const family=v=>v.toUpperCase().replace(/[\s_-]/g,'').replace(/^(PLA|PETG|ABS|TPU|ASA).*$/,'$1'),matches=(detailContext?.slots||[]).filter(t=>t.available&&t.spool_id&&family(t.material)===family(f.material)&&t.color.toUpperCase()===f.color.toUpperCase());if(matches.length===1)select.value=matches[0].slot;select.onchange=()=>{invalidatePrintReview();paintPrintPressure(select,pressure,profileLink)};label.append(select,pressure,profileLink);mappings.append(label);paintPrintPressure(select,pressure,profileLink)}byId('start-review-button').disabled=!detailContext||!detailReady||!!detailFile?.blocked}
function paintPrintPressure(select,hint,link){const tray=detailContext?.slots.find(t=>t.slot===select.value);hint.textContent=tray?'Gemeldete Drucksteuerung: '+(tray.pressure_profile||'Noch nicht gemeldet')+' · K '+(typeof tray.pressure_k==='number'?tray.pressure_k.toFixed(4):'unbekannt'):'AMS-Schacht wählen, um dessen Drucksteuerung zu prüfen.';link.hidden=!tray||tray.slot==='external';if(tray)link.href='/?ams_slot='+encodeURIComponent(tray.slot)+'#ams-panel'}
async function refreshPrintContext(){if(startingPrint)return;const generation=detailGeneration,version=++detailContextVersion,button=byId('refresh-start-context');invalidatePrintReview();button.disabled=true;byId('start-review-button').disabled=true;try{await storageJSON('/api/ams/calibrations');const ctx=await storageJSON('/api/storage/start-context');if(generation!==detailGeneration||version!==detailContextVersion)return;detailContext=ctx;if(detailMetadata)applyDetailMetadata(detailMetadata,detailReady);detailStatus('Druckerangaben aktualisiert. Profil und gemeldeten K-Faktor prüfen.')}catch(e){if(generation===detailGeneration&&version===detailContextVersion){detailContext=null;byId('start-review-button').disabled=true;detailStatus(e.message)}}finally{button.disabled=false}}
function printChoice(){return {plate:Number(byId('detail-plate').value),mapping:Object.fromEntries([...document.querySelectorAll('[data-filament]')].map(s=>[s.dataset.filament,s.value])),options:Object.fromEntries([...byId('start-options').querySelectorAll('input')].map(x=>[x.name,x.checked])),allow_mismatch:byId('start-override').checked}}
async function reviewPrintStart(){if(startingPrint||!detailReady)return;const generation=detailGeneration;invalidatePrintReview();byId('start-review-button').disabled=true;try{const choice=printChoice(),d=await storageJSON('/storage/start-review',{method:'POST',body:new URLSearchParams({file:detailFile.token,choice:JSON.stringify(choice),csrf_token:csrf})});if(generation!==detailGeneration)return;if(JSON.stringify(printChoice())!==JSON.stringify(choice)){detailStatus('Auswahl während der Prüfung geändert. Bitte erneut prüfen.');return}detailReview={token:d.token,expires:Date.now()+d.expires_in*1000,choice:JSON.stringify(choice)};const box=byId('print-start-summary');box.replaceChildren();for(const line of d.summary){const li=document.createElement('li');li.textContent=line;box.append(li)}byId('print-start-review').hidden=false;detailStatus('Startauswahl geprüft. Noch wurde kein Druck gestartet.')}catch(e){if(generation===detailGeneration)detailStatus(e.message)}finally{if(generation===detailGeneration)byId('start-review-button').disabled=!detailContext||!detailReady||!!detailFile?.blocked}}
async function confirmPrintStart(){if(startingPrint||!detailReview)return;if(!byId('start-bed-clear').checked){detailStatus('Bitte freie und vorbereitete Druckplatte bestätigen.');return}if(Date.now()>detailReview.expires||JSON.stringify(printChoice())!==detailReview.choice){invalidatePrintReview();detailStatus('Auswahl geändert oder Prüfung abgelaufen. Erneut prüfen.');return}const review=detailReview.token;detailReview=null;startingPrint=true;byId('start-confirm-button').disabled=true;byId('start-review-button').disabled=true;try{const d=await storageJSON('/storage/start',{method:'POST',body:new URLSearchParams({review,confirm:'start-print',bed_clear:'yes',csrf_token:csrf})});detailStatus(d.message)}catch(e){detailStatus(e.message+' Druckerstatus prüfen, bevor erneut gestartet wird.')}finally{startingPrint=false;byId('print-start-review').hidden=true;byId('start-confirm-button').disabled=false;byId('start-review-button').disabled=true;detailContext=null}}
window.addEventListener('pagehide',()=>cancelDetailLoad());byId('file-detail').addEventListener('close',()=>{if(!startingPrint&&!byId('file-detail').open)cancelDetailLoad()});byId('file-count').before(document.querySelector('.storage-filters'));byId('start-options').addEventListener('change',invalidatePrintReview);byId('start-override').addEventListener('change',invalidatePrintReview);byId('file-detail').addEventListener('cancel',e=>{if(startingPrint)e.preventDefault();else{e.preventDefault();closeFileDetails()}});try{if(localStorage.getItem('plus-file-view')==='cards')byId('file-view').value='cards'}catch{}
</script>
'''

EXTRA += r'''
<dialog id="rename-dialog"><h2>Datei umbenennen</h2><p id="rename-source"></p><form onsubmit="renamePrinterFile(event)"><label>Neuer Dateiname ohne Endung<input id="rename-stem" required maxlength="180" autocomplete="off"></label><p class="muted small">Dateiendung bleibt erhalten: <strong id="rename-suffix"></strong>. Vorhandene Dateien werden nicht überschrieben; Druckhistorie und Bestände bleiben erhalten.</p><p id="rename-status" role="status"></p><div class="actions"><button id="rename-confirm">Umbenennen</button><button type="button" class="quiet" onclick="document.getElementById('rename-dialog').close()">Abbrechen</button></div></form></dialog>
<style>#rename-dialog{width:min(580px,95vw);background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:16px;padding:24px}#rename-dialog::backdrop{background:#0008}</style>
<script>
let renameFile=null,renameSuffix='';function reviewFileRename(file){if(busy||startingPrint||file.blocked)return;renameFile=file;renameSuffix=['.gcode.3mf','.3mf','.gcode'].find(s=>file.name.toLowerCase().endsWith(s));byId('rename-source').textContent=file.name;byId('rename-stem').value=file.name.slice(0,-renameSuffix.length);byId('rename-suffix').textContent=renameSuffix;byId('rename-status').textContent='';byId('rename-confirm').disabled=false;byId('rename-dialog').showModal();byId('rename-stem').focus()}
async function renamePrinterFile(event){event.preventDefault();if(busy||!renameFile)return;const button=byId('rename-confirm');button.disabled=true;setFileBusy(true);try{const stem=byId('rename-stem').value.trim(),name=stem+renameSuffix;if(!stem)throw Error('Bitte einen Dateinamen eingeben.');const d=await storageJSON('/storage/rename',{method:'POST',body:new URLSearchParams({file:renameFile.token,name,csrf_token:csrf})});byId('rename-dialog').close();setFileBusy(false);await loadFiles();statusFiles(d.message)}catch(e){byId('rename-status').textContent=e.message}finally{setFileBusy(false);button.disabled=false}}
</script>
'''
